    ["圆形AOE60%HP，矩形AOE60%HP"] = "Круговой АОЕ 60% HP, прямоугольный АОЕ 60% HP",
    ["Circular AOE 60%HP, Rectangular AOE 60%HP"] = "Круговой АОЕ 60% HP, прямоугольный АОЕ 60% HP",
    ["圣光"] = "Священный Свет",
    ["Holy Light"] = "Священный Свет",
    ["圣光共鸣"] = "Резонанс Священного Света",
    ["Holy Light Resonance"] = "Резонанс Священного Света",
    ["圣光净化"] = "Очищение Священным Светом",
    ["Holy Light Purification"] = "Очищение Священным Светом",
    ["圣光回响"] = "Эхо Священного Света",
